uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;

// --- ASSETS ---
uniform sampler2D iChannel0; 
uniform sampler2D iChannel1; 

// --- STANDARD CONTROLS ---
uniform float u_speed;
uniform float u_camera_dist; 
uniform float u_fov;
uniform float u_glow_intensity;

// --- VISUAL CONTROLS ---
uniform float u_turbulence_strength;
uniform float u_cloud_height; // Reused as tunnel radius
uniform float u_color_shift;
uniform float u_density_factor;
uniform float u_tunnel_twist; 
uniform float u_exit_light_size; // New: Controls the size of the light at the end
uniform float u_exit_light_bright; // New: Controls the brightness of the light at the end

out vec4 fragColor;

// --- LUMINA MATH LIB ---
#define PI 3.14159265359

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// --- MAIN RENDER LOOP ---
void main() {
    // 1. Setup UVs and Ray Direction
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;

    // Create the ray direction for a forward-moving perspective
    vec3 rd = normalize(vec3(uv, 1.0 / u_fov)); 

    // Animation Time
    float t = iTime * u_speed;

    // Raymarching Variables
    vec4 col = vec4(0.0);
    float dist = u_camera_dist; 
    float stepSize = 0.0;

    // --- VOLUMETRIC MARCH ---
    for(int i = 0; i < 80; i++) {

        // Current Position along Ray
        vec3 p = dist * rd;
        p.z += t; // Forward motion

        // Apply twist to the tunnel based on depth
        p.xy *= rot(p.z * u_tunnel_twist + t * 0.1);

        // --- TURBULENCE LOOP (FBM) ---
        float scale = 3.0;
        for(int j = 0; j < 4; j++) {
            p += u_turbulence_strength * sin(p.yzx * scale) / scale;
            scale *= 1.8; 
            if (scale > 50.0) break;
        }

        // --- CYLINDRICAL DENSITY CALCULATION ---
        float radius = u_cloud_height * 2.0;
        float tunnelDist = length(p.xy) - radius;

        // Calculate Step Size
        float stepFactor = max(abs(tunnelDist), 0.02);
        stepSize = stepFactor * 0.4;

        // Advance Ray
        dist += stepSize;

        // --- COLOR ACCUMULATION ---
        float angle = atan(p.y, p.x);
        float hue = p.z * 0.5 + angle / PI + u_color_shift * 5.0;

        // Iridescent color mapping
        vec3 baseColor = cos(hue - vec3(0.0, 2.0, 4.0)) * 0.5 + 0.5;

        // Glow logic based on proximity to the tunnel wall
        float glow = exp(-abs(tunnelDist) * (10.0 / u_density_factor));

        // Accumulate intensity
        col.rgb += baseColor * glow * (u_glow_intensity * 0.05) / (1.0 + dist * 0.5);

        // Optimization: early exit if color is saturated
        if(col.a > 0.99) break;
    }

    // --- THE LIGHT AT THE END OF THE TUNNEL ---
    // A centralized glow that represents the exit/horizon
    float exitGlow = pow(max(0.0, 1.0 - length(uv) / u_exit_light_size), 4.0);
    vec3 exitColor = vec3(0.8, 0.9, 1.0) * exitGlow * u_exit_light_bright;

    // --- POST PROCESSING ---
    vec3 finalCol = col.rgb + exitColor;

    // Contrast and Tone Mapping
    finalCol = smoothstep(0.0, 1.2, finalCol);
    finalCol = tanh(finalCol * 1.5); 

    // Vignette
    finalCol *= 1.0 - dot(uv, uv) * 0.5;

    fragColor = vec4(finalCol, 1.0);
}
